parts.text:
[
  {
    "statement": "Several methods have been demonstrated to reduce unwanted catch in commercial fisheries.",
    "citations": []
  },
  {
    "statement": "Using larger mesh sizes showed the strongest evidence for effectiveness in reducing unwanted catch.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Fifteen of twenty studies found that larger mesh nets reduced catches of unwanted fish compared to standard or smaller mesh sizes.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Using larger mesh sizes improved size-selectivity for fish species in 19 of 21 studies.",
    "citations": [
      "2697"
    ]
  },
  {
    "statement": "Three of four studies found that modifications to gillnet configurations reduced unwanted catch of various fish species.",
    "citations": [
      "2701"
    ]
  },
  {
    "statement": "For trap fisheries, increasing mesh size appeared to reduce unwanted undersized mud crab catches in controlled studies.",
    "citations": [
      "2148",
      "2146"
    ]
  },
  {
    "statement": "For trap fisheries, fitting escape frames appeared to reduce unwanted undersized mud crab catches in controlled studies.",
    "citations": [
      "2148",
      "2146"
    ]
  },
  {
    "statement": "More technologically advanced approaches to reducing unwanted catch showed mixed but promising results.",
    "citations": []
  },
  {
    "statement": "Technology to communicate near real-time catch information to fishers reduced unwanted catch or discards in two of three cases.",
    "citations": [
      "3826"
    ]
  },
  {
    "statement": "Setting catch limits or quotas for non-target species reduced unwanted catch in two of three cases.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "Setting catch limits or quotas for non-target species reduced unwanted halibut in one study.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "Combined gear modifications also demonstrated effectiveness in reducing unwanted catch.",
    "citations": []
  },
  {
    "statement": "Trawl nets with escape grids and square mesh codends caught fewer unwanted fish species compared to diamond mesh codends with no grid.",
    "citations": [
      "2725"
    ]
  }
]
